`timescale 1ns/1ps

/* verilator lint_off UNUSEDPARAM */
package sched_pkg;
  import noc_pkg::*;

  localparam int TT_GRP_W = 4;   // group, 0..15
  localparam int SLOT_W   = 8;   // slot, 0..135 (16 x 17 / 2 slots)
  localparam int SUB_W    = 4;   // subslot, 0..15
  localparam int TCYC_W   = 7;   // cycle inside a setup window or a subslot, 0..127
  localparam int HOP_W    = 5;   // hops on a path, 0..30

  typedef logic [TT_GRP_W-1:0] tt_grp_t;
  typedef logic [SLOT_W-1:0]   slot_t;
  typedef logic [SUB_W-1:0]    sub_t;
  typedef logic [HOP_W-1:0]    hop_t;

  localparam int TM_SAFE  = 0;
  localparam int TM_TIGHT = 1;

  function automatic int hmax(int n);
    return 2 * (n - 1);
  endfunction

  function automatic int s_setup(int n);
    return hmax(n) + 1;
  endfunction

  function automatic int t_safe(int n, int bmax);
    return 2 * hmax(n) + bmax + 2;
  endfunction

  function automatic int t_tight(int n, int bmax);
    return 2 * hmax(n) + bmax - 4;
  endfunction

  function automatic int t_sub(int n, int bmax, int mode);
    return (mode == TM_SAFE) ? t_safe(n, bmax) : t_tight(n, bmax);
  endfunction

  function automatic int n_slots(int n);
    return n * (n + 1) / 2;
  endfunction

  function automatic int slot_len(int n, int t);
    return s_setup(n) + n * t;
  endfunction

  function automatic int round_len(int n, int t);
    return n_slots(n) * slot_len(n, t);
  endfunction

  function automatic int wrap(int v, int n);
    return v & (n - 1);
  endfunction

  function automatic bit pow2(int n);
    return (n > 0) && ((n & (n - 1)) == 0);
  endfunction

  function automatic slot_t tri_num(tt_grp_t n);
    slot_t r;
    case (n)
      4'd0:    r = 8'd0;
      4'd1:    r = 8'd1;
      4'd2:    r = 8'd3;
      4'd3:    r = 8'd6;
      4'd4:    r = 8'd10;
      4'd5:    r = 8'd15;
      4'd6:    r = 8'd21;
      4'd7:    r = 8'd28;
      4'd8:    r = 8'd36;
      4'd9:    r = 8'd45;
      4'd10:   r = 8'd55;
      4'd11:   r = 8'd66;
      4'd12:   r = 8'd78;
      4'd13:   r = 8'd91;
      4'd14:   r = 8'd105;
      default: r = 8'd120;
    endcase
    return r;
  endfunction

  function automatic int grp_of(int x, int y, int n);
    return wrap(x - y, n);
  endfunction

  function automatic int row_x(int w, int k, int n);
    return wrap(w + k, n);
  endfunction

  function automatic int slot_of(int a, int b);
    int lo, hi;
    lo = (a < b) ? a : b;
    hi = (a < b) ? b : a;
    return hi * (hi + 1) / 2 + lo;
  endfunction

  typedef struct packed {
    logic   vld;    // a burst goes this way in this subslot
    coord_t x;      // the partner
    coord_t y;
    logic   mode;   // MODE_XY or MODE_YX: the dimension order of the burst's path
  } partner_t;

  function automatic partner_t tx_partner(int g, int j, int o, int s, int n);
    partner_t p;
    int       r;
    p = '0;
    r = 0;
    if (o == g) begin                 // same group: to row j + s, by XY; idle when s = 0
      if (s != 0) begin
        r      = wrap(j + s, n);
        p.vld  = 1'b1;
        p.mode = MODE_XY;
      end
    end else if (g < o) begin         // lower group: to row j - s of the higher one, by XY
      r      = wrap(j - s, n);
      p.vld  = 1'b1;
      p.mode = MODE_XY;
    end else begin                    // higher group: to row j + s of the lower one, by YX
      r      = wrap(j + s, n);
      p.vld  = 1'b1;
      p.mode = MODE_YX;
    end
    if (p.vld) begin
      p.x = coord_t'(row_x(o, r, n));
      p.y = coord_t'(r);
    end
    return p;
  endfunction

  function automatic partner_t rx_partner(int g, int j, int o, int s, int n);
    partner_t p;
    int       r;
    p = '0;
    r = 0;
    if (o == g) begin                 // same group: from row j - s, by XY
      if (s != 0) begin
        r      = wrap(j - s, n);
        p.vld  = 1'b1;
        p.mode = MODE_XY;
      end
    end else if (g < o) begin         // lower group: row j - s of the higher one sends by YX
      r      = wrap(j - s, n);
      p.vld  = 1'b1;
      p.mode = MODE_YX;
    end else begin                    // higher group: row j + s of the lower one sends by XY
      r      = wrap(j + s, n);
      p.vld  = 1'b1;
      p.mode = MODE_XY;
    end
    if (p.vld) begin
      p.x = coord_t'(row_x(o, r, n));
      p.y = coord_t'(r);
    end
    return p;
  endfunction

  localparam int TC_DECIDE = 0;

  function automatic int tc_xbar(int j);
    return 1 + j;
  endfunction

  function automatic int tc_link(int i, int j);
    return 1 + 2 * i + j;
  endfunction

  function automatic int tc_la(int i);
    return 2 * i;
  endfunction

  function automatic int tc_eject(int l, int j);
    return 2 * l + 3 + j;
  endfunction

  function automatic int tc_cancel(int h);
    return h;
  endfunction

  function automatic int ej_tail(int n, int bmax, int mode);
    int e;
    e = 2 * hmax(n) + 3 + bmax - t_sub(n, bmax, mode);
    return (e > 0) ? e : 0;
  endfunction

  function automatic int byp_space(int n, int bmax, int mode);
    return 2 * bmax + ej_tail(n, bmax, mode) + 1;
  endfunction

  function automatic int ej_depth_b(int nvc, int vcd, int n, int bmax, int mode);
    return nvc * vcd + byp_space(n, bmax, mode);
  endfunction

  localparam int KL_W    = 6;       // k_L, 0..63 (K_MAX is 47 on 16x16)
  localparam int A_DELAY = 256;     // epoch tick -> plan sampled, cycles (D19)

  typedef logic [KL_W-1:0] kl_t;

  function automatic int frame_len(int n, int rg, int bmax, int mode, int kl);
    return kl * slot_len(rg, t_sub(rg, bmax, mode)) + slot_len(n, t_sub(n, bmax, mode));
  endfunction

  function automatic int k_fixed(int n, int rg, int bmax, int mode);
    int g, l;
    g = slot_len(n, t_sub(n, bmax, mode));
    l = slot_len(rg, t_sub(rg, bmax, mode));
    return (2 * g + l) / (2 * l);
  endfunction

  function automatic int k_max(int n);
    return (n >= 16) ? 47 : 15;
  endfunction

  function automatic int epoch_len(int n, int rg, int bmax, int mode);
    longint r, e;
    int     ns, fl;
    ns = n_slots(n);
    fl = frame_len(n, rg, bmax, mode, 4);
    r  = longint'(ns);
    r  = r * fl;
    e  = 1;
    for (int i = 0; i < 40; i++) begin
      if (e < r) e = e * 2;
    end
    return int'(e);
  endfunction

  localparam int DM_W      = 14;   // demand sums per tile, bits (D17)
  localparam int DM_SAMPLE = 16;   // sampling period, cycles (D17)
  localparam int K_MIN     = 1;    // smallest k_L the controller sets (D18)
  localparam int POL_PROP  = 0;    // policy: k_L = round(alpha C_L / C_G) (D18)
  localparam int POL_SQRT  = 1;    // policy: k_L = round(alpha sqrt(C_L / C_G)) (D18)
  localparam int CT_W      = 8;    // controller cycle count after a tick, saturating at 255

  function automatic int dm_sum_w(int n);
    return DM_W + $clog2(n * n);
  endfunction

  function automatic int ct_start(int x, int y, int n);
    return 2 * n - 1 - x - y;
  endfunction

  function automatic int ct_sums(int n);
    return 2 * n + dm_sum_w(n);
  endfunction

  function automatic int pair_turns(int n);
    return 2 * n * (n - 1);
  endfunction

  function automatic int kl_table(int pol, int n, int rg, int kmin, int kmax, int q);
    longint a, b, u, v, k, lhs, rhs, nr, lo, hi, t;
    int     pg, pl, ri, qi;
    pg  = pair_turns(n);
    pl  = pair_turns(rg);
    ri  = n / rg;
    qi  = 2 * q + 1;
    a   = longint'(pg);            // alpha = a / b
    b   = longint'(pl);
    nr  = longint'(ri);
    b   = b * nr * nr;
    u   = longint'(qi);
    v   = 64'sd32 - u;
    lo  = longint'(kmin);
    hi  = longint'(kmax);
    k   = 64'sd0;
    if (pol == POL_SQRT) begin
      rhs = 64'sd4 * a * a * u;
      for (int i = 1; i < 64; i++) begin
        t   = longint'(i);
        lhs = 64'sd2 * t - 64'sd1;
        lhs = lhs * lhs * b * b * v;
        if (lhs <= rhs) k = t;
      end
    end else begin
      k = (64'sd2 * a * u + b * v) / (64'sd2 * b * v);
    end
    if (k < lo) k = lo;
    if (k > hi) k = hi;
    return int'(k);
  endfunction

  typedef struct packed {
    logic              loc;      // the local timetable runs this cycle
    kl_t               kl;       // k_L of this frame
    kl_t               lc;       // local slots finished in this frame (0 in its global slot)
    logic              l_setup;  // local counter: setup window, subslot, cycle, slot
    sub_t              l_sub;
    logic [TCYC_W-1:0] l_cyc;
    slot_t             l_slot;
    logic              g_setup;  // global counter
    sub_t              g_sub;
    logic [TCYC_W-1:0] g_cyc;
    slot_t             g_slot;
  } seq_st_t;

endpackage
/* verilator lint_on UNUSEDPARAM */

// =============================================================================
// ==== rtl/common/rr_arbiter.sv
// =============================================================================
`timescale 1ns/1ps

module rr_arbiter #(
  parameter int N  = 4,                        // requesters, 1 or more
  parameter int IW = (N > 1) ? $clog2(N) : 1   // index width: derived, do not set
) (
  input  logic          clk_i,
  input  logic          rst_ni,      // asynchronous, active low
  input  logic [N-1:0]  req_i,
  input  logic [N-1:0]  mask_i,      // 1 = requester may not win this cycle
  input  logic          hold_i,      // 1 = keep the last accepted winner if eligible
  input  logic          update_i,    // 1 = grant accepted: move priority past the winner
  output logic [N-1:0]  gnt_o,       // one-hot; zero when nobody is eligible
  output logic [IW-1:0] gnt_idx_o,   // index of the winner; 0 when gnt_vld_o is 0
  output logic          gnt_vld_o    // a requester was granted
);

  logic [IW-1:0] ptr_q;        // requester with the highest priority
  logic [IW-1:0] last_q;       // last accepted winner
  logic          last_vld_q;   // last_q holds a real winner (0 after reset)

  logic [N-1:0] elig;          // eligible requests
  logic [N-1:0] elig_hi;       // eligible requests at or above the pointer
  logic [N-1:0] pick_hi;       // lowest of elig_hi
  logic [N-1:0] pick_all;      // lowest of elig: the wrap-around winner
  logic [N-1:0] last_oh;       // last_q as a one-hot vector
  logic         hold_hit;      // the hold rule decides this cycle

  assign elig     = req_i & ~mask_i;
  assign elig_hi  = elig & ({N{1'b1}} << ptr_q);
  assign pick_hi  = elig_hi & (-elig_hi);
  assign pick_all = elig & (-elig);

  always_comb begin
    last_oh         = '0;
    last_oh[last_q] = 1'b1;
  end

  assign hold_hit  = hold_i & last_vld_q & elig[last_q];
  assign gnt_o     = hold_hit ? last_oh : ((|elig_hi) ? pick_hi : pick_all);
  assign gnt_vld_o = |elig;

  always_comb begin
    gnt_idx_o = '0;
    for (int i = 0; i < N; i++) begin
      if (gnt_o[i]) gnt_idx_o = gnt_idx_o | IW'(i);
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ptr_q      <= '0;
      last_q     <= '0;
      last_vld_q <= 1'b0;
    end else if (update_i && gnt_vld_o) begin
      ptr_q      <= (gnt_idx_o == IW'(N - 1)) ? '0 : gnt_idx_o + IW'(1);
      last_q     <= gnt_idx_o;
      last_vld_q <= 1'b1;
    end
  end

endmodule

// =============================================================================
// ==== rtl/common/sync_fifo.sv
// =============================================================================
`timescale 1ns/1ps

module sync_fifo #(
  parameter int WIDTH = 8,
  parameter int DEPTH = 4,
  parameter bit CHECK = 1'b1,                            // simulation checks on
  parameter int PW    = (DEPTH > 1) ? $clog2(DEPTH) : 1, // pointer width: derived
  parameter int CW    = $clog2(DEPTH + 1)                // count width: derived
) (
  input  logic             clk_i,
  input  logic             rst_ni,     // asynchronous, active low
  input  logic             push_i,
  input  logic [WIDTH-1:0] wdata_i,
  input  logic             pop_i,
  output logic [WIDTH-1:0] rdata_o,    // oldest entry; valid while empty_o is 0
  output logic             empty_o,
  output logic             full_o,
  output logic [CW-1:0]    count_o     // entries held, 0..DEPTH
);

  logic [WIDTH-1:0] mem_q [DEPTH];
  logic [PW-1:0]    rd_q, wr_q;
  logic [CW-1:0]    cnt_q;
  logic             do_push, do_pop;

  assign empty_o = (cnt_q == '0);
  assign full_o  = (cnt_q == CW'(DEPTH));
  assign count_o = cnt_q;
  assign rdata_o = mem_q[rd_q];

  assign do_pop  = pop_i & ~empty_o;
  assign do_push = push_i & (~full_o | do_pop);

  function automatic logic [PW-1:0] next_ptr(logic [PW-1:0] p);
    return (p == PW'(DEPTH - 1)) ? '0 : p + PW'(1);
  endfunction

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rd_q  <= '0;
      wr_q  <= '0;
      cnt_q <= '0;
    end else begin
      if (do_push) wr_q <= next_ptr(wr_q);
      if (do_pop)  rd_q <= next_ptr(rd_q);
      if (do_push && !do_pop)      cnt_q <= cnt_q + CW'(1);
      else if (do_pop && !do_push) cnt_q <= cnt_q - CW'(1);
    end
  end

  always_ff @(posedge clk_i) begin
    if (do_push) mem_q[wr_q] <= wdata_i;
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else if (CHECK) begin
      if ($isunknown({push_i, pop_i}))
        $fatal(1, "%m: X on push_i or pop_i");
      if (push_i && full_o && !pop_i)
        $fatal(1, "%m: push while full (credit or allocation bug)");
      if (pop_i && empty_o)
        $fatal(1, "%m: pop while empty (allocation bug)");
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/route_compute.sv
// =============================================================================
`timescale 1ns/1ps

module route_compute
  import noc_pkg::*;
#(
  parameter int MESH_N = 8,            // mesh side, 2..16
  parameter int ALGO   = RT_ADAPTIVE   // RT_XY, RT_ADAPTIVE or RT_DOR
) (
  input  coord_t                          cur_x_i,    // this router
  input  coord_t                          cur_y_i,
  input  node_id_t                        dst_i,      // destination router
  input  logic                            mode_i,     // RT_DOR only: MODE_XY or MODE_YX
  input  logic [NPORTS-1:0][VC_CNT_W-1:0] free_vc_i,  // RT_ADAPTIVE only: free VCs at
  output port_t                           port_o
);

  coord_t              dst_x, dst_y;
  logic                x_prod, y_prod;   // a move in x (in y) brings the packet closer
  port_t               x_port, y_port;   // the productive port in x (in y)
  logic [VC_CNT_W-1:0] x_free, y_free;   // free VCs behind x_port (y_port)

  assign dst_x  = id_x(dst_i, MESH_N);
  assign dst_y  = id_y(dst_i, MESH_N);
  assign x_prod = (dst_x != cur_x_i);
  assign y_prod = (dst_y != cur_y_i);
  assign x_port = (dst_x > cur_x_i) ? P_E : P_W;
  assign y_port = (dst_y > cur_y_i) ? P_S : P_N;
  assign x_free = (dst_x > cur_x_i) ? free_vc_i[P_E] : free_vc_i[P_W];
  assign y_free = (dst_y > cur_y_i) ? free_vc_i[P_S] : free_vc_i[P_N];

  always_comb begin
    if (!x_prod && !y_prod) begin
      port_o = P_L;                                         // arrived
    end else if (ALGO == RT_ADAPTIVE) begin
      if      (!y_prod) port_o = x_port;                    // only x is productive
      else if (!x_prod) port_o = y_port;                    // only y is productive
      else              port_o = (y_free > x_free) ? y_port : x_port;   // tie: X
    end else if (ALGO == RT_DOR && mode_i == MODE_YX) begin
      port_o = y_prod ? y_port : x_port;                    // Y first
    end else begin
      port_o = x_prod ? x_port : y_port;                    // X first: RT_XY, RT_DOR in XY mode
    end
  end

  logic unused_inputs;
  assign unused_inputs = ^{mode_i, free_vc_i, x_free, y_free};

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (MESH_N < 2 || MESH_N > MAX_MESH_N)
      $fatal(1, "%m: MESH_N = %0d, must be 2..%0d", MESH_N, MAX_MESH_N);
    if (ALGO != RT_XY && ALGO != RT_ADAPTIVE && ALGO != RT_DOR)
      $fatal(1, "%m: unknown ALGO %0d", ALGO);
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/input_unit.sv
// =============================================================================
`timescale 1ns/1ps

module input_unit
  import noc_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int NUM_VC   = 4,            // 1..4
  parameter int VC_DEPTH = 5,            // flits per VC: one 5-flit packet
  parameter int ALGO     = RT_ADAPTIVE   // RT_XY or RT_ADAPTIVE
) (
  input  logic                            clk_i,
  input  logic                            rst_ni,
  input  coord_t                          cur_x_i,     // this router
  input  coord_t                          cur_y_i,
  input  flit_t                           flit_i,
  output credit_t                         credit_o,
  input  logic [NPORTS-1:0][VC_CNT_W-1:0] free_vc_i,
  output logic   [NUM_VC-1:0]             req_o,       // a flit waits at the front of the VC
  output port_t  [NUM_VC-1:0]             port_o,      // output port of the VC's packet
  output logic   [NUM_VC-1:0]             active_o,    // its output VC is already held
  output vc_id_t [NUM_VC-1:0]             outvc_o,     // that output VC
  input  logic                            gnt_i,       // the front flit of gnt_vc_i goes now
  input  vc_id_t                          gnt_vc_i,
  input  vc_id_t                          gnt_outvc_i, // output VC it travels on
  output flit_t                           sa_flit_o,
  output port_t                           sa_port_o,
  output logic   [NUM_VC-1:0]             bp_rdy_o,    // a whole packet waits, nothing sent
  output flit_t  [NUM_VC-1:0]             bp_front_o,  // front flit of each VC
  input  logic   [NUM_VC-1:0]             bp_hold_i,   // the source takes these packets now
  input  logic   [NUM_VC-1:0]             bp_pop_i     // front flit leaves for the bypass
);

  localparam int FTW = $bits(ftype_t);
  localparam int FW  = FTW + FLIT_DATA_W;   // a stored flit: type and data

  typedef enum logic [1:0] {
    VC_IDLE   = 2'd0,
    VC_ROUTED = 2'd1,
    VC_ACTIVE = 2'd2,
    VC_BYPASS = 2'd3
  } vc_state_e;

  localparam int CW  = $clog2(VC_DEPTH + 1);

  vc_state_e         state_q [NUM_VC];
  port_t             port_q  [NUM_VC];
  vc_id_t            outvc_q [NUM_VC];
  logic [NUM_VC-1:0] push, pop, gpop, empty;
  logic [FW-1:0]     rdata   [NUM_VC];
  logic [CW-1:0]     count   [NUM_VC];

  logic  wr;          // a flit for the buffers arrives
  head_t in_head;
  port_t rc_port;

  assign wr      = flit_i.vld & ~flit_i.byp;
  assign in_head = head_t'(flit_i.data);

  route_compute #(.MESH_N(MESH_N), .ALGO(ALGO)) u_rc (
    .cur_x_i   (cur_x_i),
    .cur_y_i   (cur_y_i),
    .dst_i     (in_head.dst),
    .mode_i    (MODE_XY),
    .free_vc_i (free_vc_i),
    .port_o    (rc_port)
  );

  logic [NUM_VC-1:0] unused_full;
  head_t             front_head [NUM_VC];

  for (genvar v = 0; v < NUM_VC; v++) begin : g_vc
    assign push[v] = wr & (flit_i.vc == vc_id_t'(v));
    assign gpop[v] = gnt_i & (gnt_vc_i == vc_id_t'(v));     // regular: won the switch
    assign pop[v]  = gpop[v] | bp_pop_i[v];                 // or taken by the bypass

    sync_fifo #(.WIDTH(FW), .DEPTH(VC_DEPTH)) u_buf (
      .clk_i   (clk_i),
      .rst_ni  (rst_ni),
      .push_i  (push[v]),
      .wdata_i ({flit_i.ftype, flit_i.data}),
      .pop_i   (pop[v]),
      .rdata_o (rdata[v]),
      .empty_o (empty[v]),
      .full_o  (unused_full[v]),
      .count_o (count[v])
    );

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        state_q[v] <= VC_IDLE;
        port_q[v]  <= P_L;
        outvc_q[v] <= '0;
      end else begin
        if (push[v] && is_head(flit_i.ftype)) begin
          state_q[v] <= VC_ROUTED;
          port_q[v]  <= rc_port;
        end
        if (bp_hold_i[v]) begin
          state_q[v] <= VC_BYPASS;                      // the bypass source took the packet
        end
        if (gpop[v]) begin
          if (is_tail(rdata[v][FW-1 -: FTW])) begin
            state_q[v] <= VC_IDLE;                      // the packet has left
          end else if (is_head(rdata[v][FW-1 -: FTW])) begin
            state_q[v] <= VC_ACTIVE;                    // head won a VC and the switch
            outvc_q[v] <= gnt_outvc_i;
          end
        end
        if (bp_pop_i[v] && is_tail(rdata[v][FW-1 -: FTW])) begin
          state_q[v] <= VC_IDLE;                        // the bypassed packet has left
        end
      end
    end

    assign req_o[v]    = ~empty[v] & (state_q[v] == VC_ROUTED || state_q[v] == VC_ACTIVE) & ~bp_hold_i[v];
    assign port_o[v]   = port_q[v];
    assign active_o[v] = (state_q[v] == VC_ACTIVE);
    assign outvc_o[v]  = outvc_q[v];

    assign front_head[v] = head_t'(rdata[v][FLIT_DATA_W-1:0]);
    assign bp_rdy_o[v]   = (state_q[v] == VC_ROUTED) && (int'(count[v]) == int'(front_head[v].len));
    always_comb begin
      bp_front_o[v]       = '0;
      bp_front_o[v].vld   = ~empty[v];
      bp_front_o[v].ftype = rdata[v][FW-1 -: FTW];
      bp_front_o[v].vc    = vc_id_t'(v);
      bp_front_o[v].data  = rdata[v][FLIT_DATA_W-1:0];
    end
  end

  logic [FW-1:0] gnt_data;      // front flit of the granted VC
  port_t         gnt_port;

  always_comb begin
    gnt_data = rdata[0];
    gnt_port = port_q[0];
    for (int v = 1; v < NUM_VC; v++) begin
      if (gnt_vc_i == vc_id_t'(v)) begin
        gnt_data = rdata[v];
        gnt_port = port_q[v];
      end
    end
  end

  logic   bp_any;
  vc_id_t bp_vc;
  ftype_t bp_ftype;

  always_comb begin
    bp_any   = |bp_pop_i;
    bp_vc    = '0;
    bp_ftype = rdata[0][FW-1 -: FTW];
    for (int v = 0; v < NUM_VC; v++) begin
      if (bp_pop_i[v]) begin
        bp_vc    = vc_id_t'(v);
        bp_ftype = rdata[v][FW-1 -: FTW];
      end
    end
  end

  logic                   sa_vld_q;
  ftype_t                 sa_ftype_q;
  vc_id_t                 sa_vc_q;
  logic [FLIT_DATA_W-1:0] sa_data_q;
  port_t                  sa_port_q;
  credit_t                credit_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      sa_vld_q <= 1'b0;
      credit_q <= '0;
    end else begin
      sa_vld_q         <= gnt_i;
      credit_q.vld     <= gnt_i | bp_any;
      credit_q.vc      <= gnt_i ? gnt_vc_i : bp_vc;
      credit_q.vc_free <= gnt_i ? is_tail(gnt_data[FW-1 -: FTW]) : (bp_any & is_tail(bp_ftype));
    end
  end

  always_ff @(posedge clk_i) begin
    if (gnt_i) begin
      sa_ftype_q <= gnt_data[FW-1 -: FTW];
      sa_vc_q    <= gnt_outvc_i;
      sa_data_q  <= gnt_data[FLIT_DATA_W-1:0];
      sa_port_q  <= gnt_port;
    end
  end

  always_comb begin
    sa_flit_o       = '0;
    sa_flit_o.vld   = sa_vld_q;
    sa_flit_o.ftype = sa_ftype_q;
    sa_flit_o.vc    = sa_vc_q;
    sa_flit_o.data  = sa_data_q;
  end

  assign sa_port_o = sa_port_q;
  assign credit_o  = credit_q;

  logic unused_bits;
  always_comb begin
    unused_bits = ^{unused_full, in_head.rsvd_hi, in_head.check, in_head.t_create,
                    in_head.seq, in_head.len, in_head.rsvd_lo, in_head.cls, in_head.src};
    for (int v = 0; v < NUM_VC; v++)
      unused_bits = unused_bits ^ (^{front_head[v].rsvd_hi, front_head[v].check, front_head[v].t_create,
                                     front_head[v].seq, front_head[v].rsvd_lo, front_head[v].cls,
                                     front_head[v].src, front_head[v].dst});
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else begin
      if ($isunknown({flit_i.vld, gnt_i}))
        $fatal(1, "%m: X on flit_i.vld or gnt_i");
      if (wr && int'(flit_i.vc) >= NUM_VC)
        $fatal(1, "%m: flit for VC %0d, only %0d VCs", flit_i.vc, NUM_VC);
      if (gnt_i && (int'(gnt_vc_i) >= NUM_VC || !(|(req_o & (NUM_VC'(1) << gnt_vc_i)))))
        $fatal(1, "%m: grant for VC %0d, which has nothing to send", gnt_vc_i);
      for (int v = 0; v < NUM_VC; v++) begin
        if (push[v] && is_head(flit_i.ftype) && state_q[v] != VC_IDLE)
          $fatal(1, "%m: head arrived on VC %0d, which still holds a packet", v);
        if (push[v] && !is_head(flit_i.ftype) && state_q[v] == VC_IDLE)
          $fatal(1, "%m: body or tail arrived on idle VC %0d", v);
        if (push[v] && state_q[v] == VC_BYPASS)
          $fatal(1, "%m: flit arrived on VC %0d, whose whole packet the bypass already took", v);
        if (bp_hold_i[v] && !bp_rdy_o[v])
          $fatal(1, "%m: bypass took VC %0d, which holds no whole waiting packet", v);
        if (bp_pop_i[v] && (state_q[v] != VC_BYPASS || empty[v]))
          $fatal(1, "%m: bypass pop from VC %0d in state %0d (empty %0b)", v, state_q[v], empty[v]);
      end
      if ($isunknown({bp_hold_i, bp_pop_i}))
        $fatal(1, "%m: X on bp_hold_i or bp_pop_i");
      if ($countones(bp_pop_i) > 1 || (bp_any && gnt_i))
        $fatal(1, "%m: two flits leave in one cycle (bypass pops %b, switch grant %0b)", bp_pop_i, gnt_i);
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/output_unit.sv
// =============================================================================
`timescale 1ns/1ps

module output_unit
  import noc_pkg::*;
#(
  parameter int NUM_VC   = 4,   // 1..4
  parameter int VC_DEPTH = 5    // flits per downstream VC
) (
  input  logic                clk_i,
  input  logic                rst_ni,
  input  credit_t             credit_i,
  input  logic                gnt_i,       // a flit is granted to this output
  input  logic                alloc_i,     // it is a head and takes alloc_vc_o
  input  vc_id_t              gnt_vc_i,    // output VC the flit travels on
  output logic                has_free_o,  // at least one output VC is idle
  output vc_id_t              alloc_vc_o,  // lowest idle VC; valid with has_free_o
  output logic [NUM_VC-1:0]   credit_ok_o, // per VC: at least one credit
  output logic [VC_CNT_W-1:0] free_cnt_o,  // number of idle VCs
  input  flit_t               st_flit_i,
  output flit_t               link_o
);

  localparam int CRW = $clog2(VC_DEPTH + 1);

  logic [NUM_VC-1:0] busy_q;               // VC held by a packet
  logic [CRW-1:0]    cred_q [NUM_VC];      // free buffer slots downstream
  logic [NUM_VC-1:0] inc, dec, take, rel;  // per VC this cycle

  for (genvar v = 0; v < NUM_VC; v++) begin : g_vc
    assign inc[v]  = credit_i.vld & (credit_i.vc == vc_id_t'(v));
    assign dec[v]  = gnt_i & (gnt_vc_i == vc_id_t'(v));
    assign take[v] = alloc_i & (gnt_vc_i == vc_id_t'(v));
    assign rel[v]  = inc[v] & credit_i.vc_free;
    assign credit_ok_o[v] = (cred_q[v] != '0);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      busy_q <= '0;
      for (int v = 0; v < NUM_VC; v++) cred_q[v] <= CRW'(VC_DEPTH);
    end else begin
      for (int v = 0; v < NUM_VC; v++) begin
        if (inc[v] && !dec[v])      cred_q[v] <= cred_q[v] + CRW'(1);
        else if (dec[v] && !inc[v]) cred_q[v] <= cred_q[v] - CRW'(1);
        if (take[v])     busy_q[v] <= 1'b1;
        else if (rel[v]) busy_q[v] <= 1'b0;
      end
    end
  end

  always_comb begin
    alloc_vc_o = '0;
    has_free_o = 1'b0;
    for (int v = NUM_VC - 1; v >= 0; v--) begin
      if (!busy_q[v]) begin
        alloc_vc_o = vc_id_t'(v);
        has_free_o = 1'b1;
      end
    end
  end

  always_comb begin
    free_cnt_o = '0;
    for (int v = 0; v < NUM_VC; v++) free_cnt_o = free_cnt_o + VC_CNT_W'(!busy_q[v]);
  end

  logic  link_vld_q;
  flit_t link_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) link_vld_q <= 1'b0;
    else         link_vld_q <= st_flit_i.vld;
  end

  always_ff @(posedge clk_i) begin
    if (st_flit_i.vld) link_q <= st_flit_i;
  end

  always_comb begin
    link_o     = link_q;
    link_o.vld = link_vld_q;
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else begin
      if ($isunknown({credit_i.vld, gnt_i, alloc_i}))
        $fatal(1, "%m: X on credit_i.vld, gnt_i or alloc_i");
      if (credit_i.vld && int'(credit_i.vc) >= NUM_VC)
        $fatal(1, "%m: credit for VC %0d, only %0d VCs", credit_i.vc, NUM_VC);
      if (gnt_i && int'(gnt_vc_i) >= NUM_VC)
        $fatal(1, "%m: grant on VC %0d, only %0d VCs", gnt_vc_i, NUM_VC);
      if (alloc_i && (!has_free_o || gnt_vc_i != alloc_vc_o))
        $fatal(1, "%m: head given VC %0d, the offered idle VC is %0d (any idle: %0b)",
               gnt_vc_i, alloc_vc_o, has_free_o);
      for (int v = 0; v < NUM_VC; v++) begin
        if (dec[v] && !inc[v] && cred_q[v] == '0)
          $fatal(1, "%m: flit sent on VC %0d without a credit", v);
        if (inc[v] && !dec[v] && int'(cred_q[v]) == VC_DEPTH)
          $fatal(1, "%m: credit for VC %0d beyond the buffer depth %0d", v, VC_DEPTH);
        if (dec[v] && !take[v] && !busy_q[v])
          $fatal(1, "%m: flit sent on VC %0d, which no packet holds", v);
        if (rel[v] && !busy_q[v])
          $fatal(1, "%m: VC %0d freed but it was idle", v);
        if (rel[v] && int'(cred_q[v]) + 1 - int'(dec[v]) != VC_DEPTH)
          $fatal(1, "%m: VC %0d freed with %0d of %0d credits home", v,
                 int'(cred_q[v]) + 1 - int'(dec[v]), VC_DEPTH);
      end
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/switch_allocator.sv
// =============================================================================
`timescale 1ns/1ps

module switch_allocator
  import noc_pkg::*;
#(
  parameter int NUM_VC = 4,                              // 1..4
  parameter int VCI_W  = (NUM_VC > 1) ? $clog2(NUM_VC) : 1, // derived, do not set
  parameter int PI_W   = $clog2(NPORTS)                  // derived, do not set
) (
  input  logic                            clk_i,
  input  logic                            rst_ni,
  input  logic   [NPORTS-1:0][NUM_VC-1:0] req_i,       // a flit waits at the front
  input  port_t  [NPORTS-1:0][NUM_VC-1:0] port_i,      // its output port
  input  logic   [NPORTS-1:0][NUM_VC-1:0] active_i,    // its packet holds an output VC
  input  vc_id_t [NPORTS-1:0][NUM_VC-1:0] outvc_i,     // that output VC
  input  logic   [NPORTS-1:0]             has_free_i,  // an output VC is idle
  input  vc_id_t [NPORTS-1:0]             alloc_vc_i,  // the lowest idle one
  input  logic   [NPORTS-1:0][NUM_VC-1:0] credit_ok_i, // per output VC: a credit is left
  input  logic   [NPORTS-1:0]             in_mask_i,
  input  logic   [NPORTS-1:0]             out_mask_i,
  output logic   [NPORTS-1:0]             in_gnt_o,    // input i sends a flit
  output vc_id_t [NPORTS-1:0]             in_vc_o,     // from this VC
  output vc_id_t [NPORTS-1:0]             in_outvc_o,  // on this output VC
  output logic   [NPORTS-1:0]             out_gnt_o,   // output o gets a flit
  output logic   [NPORTS-1:0]             out_alloc_o, // a head that takes alloc_vc_i[o]
  output vc_id_t [NPORTS-1:0]             out_vc_o     // the output VC used
);

  logic [NPORTS-1:0][NUM_VC-1:0] elig;

  always_comb begin
    port_t p;      // output port of VC (i, v)
    logic  cok;    // its output VC has a credit
    for (int i = 0; i < NPORTS; i++) begin
      for (int v = 0; v < NUM_VC; v++) begin
        p   = port_i[i][v];
        cok = 1'b0;
        for (int k = 0; k < NUM_VC; k++) begin
          if (outvc_i[i][v] == vc_id_t'(k)) cok = credit_ok_i[p][k];
        end
        elig[i][v] = req_i[i][v] & ~in_mask_i[i] & ~out_mask_i[p] &
                     (active_i[i][v] ? cok : has_free_i[p]);
      end
    end
  end

  logic   [NPORTS-1:0]             in_vld;     // the input has a competing VC
  logic   [NPORTS-1:0][VCI_W-1:0]  in_idx;     // which one
  port_t  [NPORTS-1:0]             in_port;    // the output port it wants
  logic   [NPORTS-1:0]             in_act;     // it already holds an output VC
  logic   [NPORTS-1:0][NUM_VC-1:0] unused_in_oh;

  for (genvar i = 0; i < NPORTS; i++) begin : g_in
    rr_arbiter #(.N(NUM_VC)) u_arb (
      .clk_i     (clk_i),
      .rst_ni    (rst_ni),
      .req_i     (elig[i]),
      .mask_i    ('0),
      .hold_i    (1'b0),
      .update_i  (in_gnt_o[i]),     // move only when the VC won its output too
      .gnt_o     (unused_in_oh[i]),
      .gnt_idx_o (in_idx[i]),
      .gnt_vld_o (in_vld[i])
    );
    assign in_port[i] = port_i[i][in_idx[i]];
    assign in_act[i]  = active_i[i][in_idx[i]];
  end

  logic [NPORTS-1:0][NPORTS-1:0] oreq;   // [o][i]: input i wants output o
  logic [NPORTS-1:0][NPORTS-1:0] ognt;   // [o][i]: one-hot winner of output o
  logic [NPORTS-1:0][PI_W-1:0]   owin;   // index of the winner of output o

  for (genvar o = 0; o < NPORTS; o++) begin : g_out
    for (genvar i = 0; i < NPORTS; i++) begin : g_req
      assign oreq[o][i] = in_vld[i] & (in_port[i] == port_t'(o));
    end
    rr_arbiter #(.N(NPORTS)) u_arb (
      .clk_i     (clk_i),
      .rst_ni    (rst_ni),
      .req_i     (oreq[o]),
      .mask_i    ('0),
      .hold_i    (1'b0),
      .update_i  (out_gnt_o[o]),
      .gnt_o     (ognt[o]),
      .gnt_idx_o (owin[o]),
      .gnt_vld_o (out_gnt_o[o])
    );
  end

  always_comb begin
    for (int i = 0; i < NPORTS; i++) begin
      in_gnt_o[i] = 1'b0;
      for (int o = 0; o < NPORTS; o++) in_gnt_o[i] = in_gnt_o[i] | ognt[o][i];
      in_vc_o[i]    = vc_id_t'(in_idx[i]);
      in_outvc_o[i] = in_act[i] ? outvc_i[i][in_idx[i]] : alloc_vc_i[in_port[i]];
    end
  end

  always_comb begin
    for (int o = 0; o < NPORTS; o++) begin
      out_alloc_o[o] = out_gnt_o[o] & ~in_act[owin[o]];
      out_vc_o[o]    = in_outvc_o[owin[o]];
    end
  end

endmodule

// =============================================================================
// ==== rtl/router/crossbar.sv
// =============================================================================
`timescale 1ns/1ps

module crossbar
  import noc_pkg::*;
(
  input  logic                clk_i,
  input  logic                rst_ni,
  input  flit_t [NPORTS-1:0]  sa_flit_i,
  input  port_t [NPORTS-1:0]  sa_port_i,
  input  logic  [NPORTS-1:0]  byp_en_i,
  input  flit_t [NPORTS-1:0]  byp_flit_i,
  input  port_t [NPORTS-1:0]  byp_port_i,
  output flit_t [NPORTS-1:0]  st_flit_o
);

  flit_t [NPORTS-1:0]             src;
  port_t [NPORTS-1:0]             src_port;
  logic  [NPORTS-1:0][NPORTS-1:0] hit;       // [o][i]: input i goes to output o
  logic  [NPORTS-1:0][FLIT_W-1:0] sel;       // flit chosen for output o

  always_comb begin
    for (int i = 0; i < NPORTS; i++) begin
      src[i]      = byp_en_i[i] ? byp_flit_i[i] : sa_flit_i[i];
      src_port[i] = byp_en_i[i] ? byp_port_i[i] : sa_port_i[i];
    end
    for (int o = 0; o < NPORTS; o++) begin
      sel[o] = '0;
      for (int i = 0; i < NPORTS; i++) begin
        hit[o][i] = src[i].vld & (src_port[i] == port_t'(o));
        sel[o]    = sel[o] | ({FLIT_W{hit[o][i]}} & FLIT_W'(src[i]));
      end
    end
  end

  logic  [NPORTS-1:0] st_vld_q;
  flit_t [NPORTS-1:0] st_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) st_vld_q <= '0;
    else for (int o = 0; o < NPORTS; o++) st_vld_q[o] <= |hit[o];
  end

  always_ff @(posedge clk_i) begin
    for (int o = 0; o < NPORTS; o++) begin
      if (|hit[o]) st_q[o] <= flit_t'(sel[o]);
    end
  end

  always_comb begin
    for (int o = 0; o < NPORTS; o++) begin
      st_flit_o[o]     = st_q[o];
      st_flit_o[o].vld = st_vld_q[o];
    end
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else begin
      for (int o = 0; o < NPORTS; o++) begin
        if ($countones(hit[o]) > 1)
          $fatal(1, "%m: inputs %b all want output %0d in the same cycle", hit[o], o);
      end
      for (int i = 0; i < NPORTS; i++) begin
        if (src[i].vld && int'(src_port[i]) >= NPORTS)
          $fatal(1, "%m: input %0d sends to port %0d, which does not exist", i, src_port[i]);
      end
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/router.sv
// =============================================================================
`timescale 1ns/1ps

module router
  import noc_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int NUM_VC   = 4,            // 1..4
  parameter int VC_DEPTH = 5,            // flits per VC
  parameter int ALGO     = RT_ADAPTIVE,  // regular routing: RT_XY or RT_ADAPTIVE
  parameter int DESIGN   = DESIGN_A,     // DESIGN_A: no bypass; B-D: bypass datapath
  parameter int B_MAX    = 10            // flits per bypass burst (designs B-D)
) (
  input  logic                    clk_i,
  input  logic                    rst_ni,
  input  coord_t                  cur_x_i,
  input  coord_t                  cur_y_i,
  input  flit_t   [NPORTS-1:0]    in_flit_i,
  output credit_t [NPORTS-1:0]    in_credit_o,
  output flit_t   [NPORTS-1:0]    out_flit_o,
  input  credit_t [NPORTS-1:0]    out_credit_i,
  input  la_t     [3:0]           in_la_i,
  output la_t     [3:0]           out_la_o,
  input  cx_t     [3:0]           in_cx_i,
  output cx_t     [3:0]           out_cx_o,
  input  cx_t                     cx_inj_i,
  output la_t                     la_loc_o,
  input  logic                    tx_go_i,
  input  node_id_t                tx_dst_i,
  input  logic                    tx_mode_i
);

  logic   [NPORTS-1:0][NUM_VC-1:0]   req, active;
  port_t  [NPORTS-1:0][NUM_VC-1:0]   vc_port;
  vc_id_t [NPORTS-1:0][NUM_VC-1:0]   outvc;
  logic   [NPORTS-1:0]               has_free;
  vc_id_t [NPORTS-1:0]               alloc_vc;
  logic   [NPORTS-1:0][NUM_VC-1:0]   credit_ok;
  logic   [NPORTS-1:0][VC_CNT_W-1:0] free_cnt;
  logic   [NPORTS-1:0]               in_gnt, out_gnt, out_alloc;
  vc_id_t [NPORTS-1:0]               in_vc, in_outvc, out_vc;
  flit_t  [NPORTS-1:0]               sa_flit, st_flit;
  port_t  [NPORTS-1:0]               sa_port;
  logic   [NPORTS-1:0]               in_mask, out_mask, byp_en;
  flit_t  [NPORTS-1:0]               byp_flit;
  port_t  [NPORTS-1:0]               byp_port;
  logic   [NPORTS-1:0][NUM_VC-1:0]   bp_rdy, bp_hold, bp_pop;
  flit_t  [NPORTS-1:0][NUM_VC-1:0]   bp_front;
  logic                              bp_busy;     // a burst or lookahead is inside (testbench idle check)

`ifndef SYNTHESIS
  // the synthesis-off pragmas, so every simulator keeps it)
  logic   [NPORTS-1:0]               tb_hold;     // test hold, set only by a directed test
  initial tb_hold = '0;
`endif

  for (genvar p = 0; p < NPORTS; p++) begin : g_port
    input_unit #(
      .MESH_N   (MESH_N),
      .NUM_VC   (NUM_VC),
      .VC_DEPTH (VC_DEPTH),
      .ALGO     (ALGO)
    ) u_in (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .cur_x_i     (cur_x_i),
      .cur_y_i     (cur_y_i),
      .flit_i      (in_flit_i[p]),
      .credit_o    (in_credit_o[p]),
      .free_vc_i   (free_cnt),
      .req_o       (req[p]),
      .port_o      (vc_port[p]),
      .active_o    (active[p]),
      .outvc_o     (outvc[p]),
      .gnt_i       (in_gnt[p]),
      .gnt_vc_i    (in_vc[p]),
      .gnt_outvc_i (in_outvc[p]),
      .sa_flit_o   (sa_flit[p]),
      .sa_port_o   (sa_port[p]),
      .bp_rdy_o    (bp_rdy[p]),
      .bp_front_o  (bp_front[p]),
      .bp_hold_i   (bp_hold[p]),
      .bp_pop_i    (bp_pop[p])
    );

    output_unit #(
      .NUM_VC   (NUM_VC),
      .VC_DEPTH (VC_DEPTH)
    ) u_out (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .credit_i    (out_credit_i[p]),
      .gnt_i       (out_gnt[p]),
      .alloc_i     (out_alloc[p]),
      .gnt_vc_i    (out_vc[p]),
      .has_free_o  (has_free[p]),
      .alloc_vc_o  (alloc_vc[p]),
      .credit_ok_o (credit_ok[p]),
      .free_cnt_o  (free_cnt[p]),
      .st_flit_i   (st_flit[p]),
      .link_o      (out_flit_o[p])
    );
  end

  switch_allocator #(.NUM_VC(NUM_VC)) u_sa (
    .clk_i       (clk_i),
    .rst_ni      (rst_ni),
    .req_i       (req),
    .port_i      (vc_port),
    .active_i    (active),
    .outvc_i     (outvc),
    .has_free_i  (has_free),
    .alloc_vc_i  (alloc_vc),
    .credit_ok_i (credit_ok),
    .in_mask_i   (in_mask),
    .out_mask_i  (out_mask),
    .in_gnt_o    (in_gnt),
    .in_vc_o     (in_vc),
    .in_outvc_o  (in_outvc),
    .out_gnt_o   (out_gnt),
    .out_alloc_o (out_alloc),
    .out_vc_o    (out_vc)
  );

  crossbar u_xb (
    .clk_i      (clk_i),
    .rst_ni     (rst_ni),
    .sa_flit_i  (sa_flit),
    .sa_port_i  (sa_port),
    .byp_en_i   (byp_en),
    .byp_flit_i (byp_flit),
    .byp_port_i (byp_port),
    .st_flit_o  (st_flit)
  );

  if (DESIGN == DESIGN_A) begin : g_no_bypass
    assign in_mask  = '0;
    assign out_mask = '0;
    assign byp_en   = '0;
    assign byp_flit = '0;
    assign byp_port = '0;
    assign bp_hold  = '0;
    assign bp_pop   = '0;
    assign out_la_o = '0;
    assign out_cx_o = '0;
    assign la_loc_o = '0;
    assign bp_busy  = 1'b0;
    logic unused_bp;
    assign unused_bp = ^{bp_rdy, bp_front, in_la_i, tx_go_i, tx_dst_i, tx_mode_i, bp_busy, in_cx_i, cx_inj_i};
`ifndef SYNTHESIS
    logic unused_hold;
    assign unused_hold = ^tb_hold;
`endif
  end else begin : g_bypass
    logic  [NPORTS-1:0] src_in_mask, src_out_mask, rl_in_mask, rl_out_mask;
    logic               src_la_vld, src_busy, rl_busy, cx_hit, cx_busy;
    port_t              src_la_port;
    la_t                src_la;
    logic  [3:0]        rl_en;
    flit_t [3:0]        rl_flit;
    port_t [3:0]        rl_port;

    bypass_source #(
      .MESH_N (MESH_N),
      .NUM_VC (NUM_VC),
      .B_MAX  (B_MAX)
    ) u_src (
      .clk_i      (clk_i),
      .rst_ni     (rst_ni),
      .cur_x_i    (cur_x_i),
      .cur_y_i    (cur_y_i),
      .tx_go_i    (tx_go_i),
      .tx_dst_i   (tx_dst_i),
      .tx_mode_i  (tx_mode_i),
      .cancel_i   (cx_hit),
      .rdy_i      (bp_rdy),
      .front_i    (bp_front),
      .hold_o     (bp_hold),
      .pop_o      (bp_pop),
      .xb_en_o    (byp_en[P_L]),
      .xb_flit_o  (byp_flit[P_L]),
      .xb_port_o  (byp_port[P_L]),
      .in_mask_o  (src_in_mask),
      .out_mask_o (src_out_mask),
      .la_vld_o   (src_la_vld),
      .la_port_o  (src_la_port),
      .la_o       (src_la),
      .busy_o     (src_busy)
    );

    bypass_relay #(
      .MESH_N (MESH_N),
      .B_MAX  (B_MAX)
    ) u_relay (
      .clk_i         (clk_i),
      .rst_ni        (rst_ni),
      .cur_x_i       (cur_x_i),
      .cur_y_i       (cur_y_i),
      .la_i          (in_la_i),
      .flit_i        (in_flit_i[3:0]),
      .src_la_vld_i  (src_la_vld),
      .src_la_port_i (src_la_port),
      .src_la_i      (src_la),
      .xb_en_o       (rl_en),
      .xb_flit_o     (rl_flit),
      .xb_port_o     (rl_port),
      .in_mask_o     (rl_in_mask),
      .out_mask_o    (rl_out_mask),
      .la_o          (out_la_o),
      .la_loc_o      (la_loc_o),
      .busy_o        (rl_busy)
    );

    cancel_relay #(.MESH_N(MESH_N)) u_cxr (
      .clk_i   (clk_i),
      .rst_ni  (rst_ni),
      .cur_x_i (cur_x_i),
      .cur_y_i (cur_y_i),
      .cx_i    (in_cx_i),
      .inj_i   (cx_inj_i),
      .cx_o    (out_cx_o),
      .hit_o   (cx_hit),
      .busy_o  (cx_busy)
    );

    assign byp_en[3:0]   = rl_en;
    assign byp_flit[3:0] = rl_flit;
    assign byp_port[3:0] = rl_port;
    assign out_mask      = src_out_mask | rl_out_mask;
    assign bp_busy       = src_busy | rl_busy | cx_busy;
    logic unused_busy;                 // read by the testbench only
    assign unused_busy   = bp_busy;
`ifndef SYNTHESIS
    assign in_mask       = src_in_mask | rl_in_mask | tb_hold;

    longint unsigned n_rule;
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        n_rule <= 0;
      end else begin
        for (int p = 0; p < 4; p++) begin
          if ((|bp_pop[p]) && rl_en[p]) n_rule <= n_rule + 1;
        end
      end
    end
`else
    assign in_mask       = src_in_mask | rl_in_mask;
`endif
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (NUM_VC < 1 || NUM_VC > MAX_VC)
      $fatal(1, "%m: NUM_VC = %0d, must be 1..%0d", NUM_VC, MAX_VC);
    if (VC_DEPTH < MAX_PKT_FLITS)
      $fatal(1, "%m: VC_DEPTH = %0d cannot hold a %0d-flit packet", VC_DEPTH, MAX_PKT_FLITS);
    if (ALGO != RT_XY && ALGO != RT_ADAPTIVE)
      $fatal(1, "%m: regular routing must be RT_XY or RT_ADAPTIVE, not %0d", ALGO);
    if (DESIGN < DESIGN_A || DESIGN > DESIGN_D)
      $fatal(1, "%m: DESIGN = %0d does not exist", DESIGN);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else if (DESIGN == DESIGN_A) begin
      for (int p = 0; p < NPORTS; p++) begin
        if (in_flit_i[p].vld && in_flit_i[p].byp)
          $fatal(1, "%m: bypass flit on input %0d of a design-A router", p);
      end
      if (in_la_i != '0 || tx_go_i || in_cx_i != '0 || cx_inj_i.vld)
        $fatal(1, "%m: lookahead, send order or cancel token at a design-A router");
    end else begin
      if (in_flit_i[P_L].vld && in_flit_i[P_L].byp)
        $fatal(1, "%m: bypass flit from the NI");
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/ni/ni.sv
// =============================================================================
`timescale 1ns/1ps

module ni
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int NUM_VC   = 4,     // VCs of the router's Local ports
  parameter int VC_DEPTH = 5,     // flits per VC
  parameter int EJ_DEPTH = 25,    // ejection FIFO, flits (D31; designs B-D: ej_depth_b, D48)
  parameter int BYPASS   = 0,     // 1: bypass flits arrive (designs B-D)
  parameter int B_MAX    = 10,    // flits per burst (BYPASS = 1)
  parameter int GAP0     = 15,    // decision -> start of subslot 0: the setup window (BYPASS = 1)
  parameter int GAPK     = 34,    // decision -> start of a later subslot: one subslot (BYPASS = 1)
  parameter int GAP0_L   = 15,    // the same for the local timetable (designs C, D)
  parameter int GAPK_L   = 34,
  parameter int EFW      = $clog2(EJ_DEPTH + 1)   // derived, do not set
) (
  input  logic           clk_i,
  input  logic           rst_ni,
  input  logic           inj_valid_i,
  output logic           inj_ready_o,
  input  flit_t          inj_flit_i,   // ftype and data are used; vld, vc, byp are not
  output flit_t          link_o,
  input  credit_t        credit_i,
  input  flit_t          ej_link_i,
  output credit_t        credit_o,
  output logic           ej_valid_o,
  input  logic           ej_ready_i,
  output flit_t          ej_flit_o,
  output logic [EFW-1:0] ej_free_o,    // free FIFO slots
  output flit_t          ej_mon_o,     // the router's Local output link
  input  logic           dec_i,
  input  logic           dec_s0_i,     // ... it is subslot 0
  input  logic           dec_loc_i,    // ... of the local timetable (designs C, D)
  input  node_id_t       dec_src_i,    // ... from this source
  input  logic           dec_mode_i,   // ... by this mode
  input  hop_t           dec_hops_i,   // ... over this many hops
  input  la_t            la_loc_i,     // the router: lookahead of a burst for this NI
  output cx_t            cx_o          // to the router: cancel token
);

  logic                in_pkt_q;       // a packet is part way through
  vc_id_t              cur_vc_q;       // its VC
  logic                has_free;
  vc_id_t              alloc_vc;
  logic [NUM_VC-1:0]   credit_ok;
  logic [VC_CNT_W-1:0] unused_free_cnt;
  logic                head, cur_cok, acc;
  vc_id_t              use_vc;
  flit_t               inj_st;

  assign head = is_head(inj_flit_i.ftype);

  always_comb begin
    cur_cok = 1'b0;
    for (int v = 0; v < NUM_VC; v++) begin
      if (cur_vc_q == vc_id_t'(v)) cur_cok = credit_ok[v];
    end
  end

  assign inj_ready_o = head ? (!in_pkt_q && has_free) : (in_pkt_q && cur_cok);
  assign acc         = inj_valid_i & inj_ready_o;
  assign use_vc      = head ? alloc_vc : cur_vc_q;

  always_comb begin
    inj_st       = '0;
    inj_st.vld   = acc;
    inj_st.ftype = inj_flit_i.ftype;
    inj_st.vc    = use_vc;
    inj_st.data  = inj_flit_i.data;
  end

  output_unit #(.NUM_VC(NUM_VC), .VC_DEPTH(VC_DEPTH)) u_inj (
    .clk_i       (clk_i),
    .rst_ni      (rst_ni),
    .credit_i    (credit_i),
    .gnt_i       (acc),
    .alloc_i     (acc & head),
    .gnt_vc_i    (use_vc),
    .has_free_o  (has_free),
    .alloc_vc_o  (alloc_vc),
    .credit_ok_o (credit_ok),
    .free_cnt_o  (unused_free_cnt),
    .st_flit_i   (inj_st),
    .link_o      (link_o)
  );

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      in_pkt_q <= 1'b0;
      cur_vc_q <= '0;
    end else if (acc) begin
      if (head) cur_vc_q <= alloc_vc;
      in_pkt_q <= !is_tail(inj_flit_i.ftype);
    end
  end

  localparam int FTW = $bits(ftype_t);
  localparam int BW  = (BYPASS != 0) ? 1 : 0;
  localparam int EW  = BW + FTW + VC_ID_W + FLIT_DATA_W;   // stored flit: [bypass,] type, VC, data

  logic           ej_empty, unused_full, ej_pop, ej_byp;
  logic [EFW-1:0] ej_cnt;
  logic [EW-1:0]  ej_rdata, ej_wdata;
  ftype_t         ej_ftype;
  vc_id_t         ej_vc;

  if (BYPASS != 0) begin : g_byp
    localparam int SPACE = EJ_DEPTH - NUM_VC * VC_DEPTH;     // the bypass space (D48)
    assign ej_wdata = {ej_link_i.byp, ej_link_i.ftype, ej_link_i.vc, ej_link_i.data};
    assign ej_byp   = ej_rdata[EW-1];

    logic [$clog2(SPACE + 1)-1:0] res, fill;
    resv_ctrl #(
      .B_MAX (B_MAX),
      .SPACE (SPACE),
      .GAP0   (GAP0),
      .GAPK   (GAPK),
      .GAP0_L (GAP0_L),
      .GAPK_L (GAPK_L)
    ) u_resv (
      .clk_i      (clk_i),
      .rst_ni     (rst_ni),
      .dec_i      (dec_i),
      .dec_s0_i   (dec_s0_i),
      .dec_loc_i  (dec_loc_i),
      .dec_src_i  (dec_src_i),
      .dec_mode_i (dec_mode_i),
      .dec_hops_i (dec_hops_i),
      .la_i       (la_loc_i),
      .push_i     (ej_link_i.vld & ej_link_i.byp),
      .pop_i      (ej_pop & ej_byp),
      .cx_o       (cx_o),
      .res_o      (res),
      .fill_o     (fill)
    );
    logic unused_cnt;                  // the testbench reads the counts in u_resv
    assign unused_cnt = ^{res, fill};
  end else begin : g_no_byp
    assign ej_wdata = {ej_link_i.ftype, ej_link_i.vc, ej_link_i.data};
    assign ej_byp   = 1'b0;
    assign cx_o     = '0;
    logic unused_resv;
    assign unused_resv = ^{dec_i, dec_s0_i, dec_loc_i, dec_src_i, dec_mode_i, dec_hops_i, la_loc_i};
  end

  sync_fifo #(.WIDTH(EW), .DEPTH(EJ_DEPTH)) u_ej (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),
    .push_i  (ej_link_i.vld),
    .wdata_i (ej_wdata),
    .pop_i   (ej_pop),
    .rdata_o (ej_rdata),
    .empty_o (ej_empty),
    .full_o  (unused_full),
    .count_o (ej_cnt)
  );

  assign ej_ftype   = ej_rdata[FTW + VC_ID_W + FLIT_DATA_W - 1 -: FTW];
  assign ej_vc      = ej_rdata[FLIT_DATA_W +: VC_ID_W];
  assign ej_valid_o = !ej_empty;
  assign ej_pop     = ej_valid_o & ej_ready_i;
  assign ej_free_o  = EFW'(EJ_DEPTH) - ej_cnt;
  assign ej_mon_o   = ej_link_i;

  always_comb begin
    ej_flit_o       = '0;
    ej_flit_o.vld   = ej_valid_o;
    ej_flit_o.ftype = ej_ftype;
    ej_flit_o.vc    = ej_vc;
    ej_flit_o.byp   = ej_byp;
    ej_flit_o.data  = ej_rdata[FLIT_DATA_W-1:0];
  end

  credit_t credit_q;
  logic    cred;

  assign cred = ej_pop & ~ej_byp;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      credit_q <= '0;
    end else begin
      credit_q.vld     <= cred;
      credit_q.vc_free <= cred & is_tail(ej_ftype);
      if (cred) credit_q.vc <= ej_vc;
    end
  end

  assign credit_o = credit_q;

  logic unused_bits;
  assign unused_bits = ^{inj_flit_i.vld, inj_flit_i.vc, inj_flit_i.byp, ej_link_i.byp,
                         unused_full, unused_free_cnt};

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (EJ_DEPTH < NUM_VC * VC_DEPTH)
      $fatal(1, "%m: EJ_DEPTH = %0d is below NUM_VC * VC_DEPTH = %0d", EJ_DEPTH, NUM_VC * VC_DEPTH);
    if (BYPASS != 0 && EJ_DEPTH < NUM_VC * VC_DEPTH + B_MAX)
      $fatal(1, "%m: EJ_DEPTH = %0d leaves no space for a burst of %0d flits beside %0d regular ones",
             EJ_DEPTH, B_MAX, NUM_VC * VC_DEPTH);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else begin
      if ($isunknown({inj_valid_i, ej_ready_i, ej_link_i.vld}))
        $fatal(1, "%m: X on inj_valid_i, ej_ready_i or the ejection link valid bit");
      if (inj_valid_i && head && in_pkt_q)
        $fatal(1, "%m: core offered a head before the tail of its previous packet");
      if (inj_valid_i && !head && !in_pkt_q)
        $fatal(1, "%m: core offered a body or tail flit without a head");
      if (ej_link_i.vld && unused_full && !ej_pop)
        $fatal(1, "%m: ejection FIFO overflow: a flit arrived with no free slot");
      if (BYPASS == 0 && ej_link_i.vld && ej_link_i.byp)
        $fatal(1, "%m: bypass flit at the NI of a design without bypass");
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/top/tile.sv
// =============================================================================
`timescale 1ns/1ps

module tile
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int NUM_VC   = 4,
  parameter int VC_DEPTH = 5,
  parameter int ALGO     = RT_XY,      // design A routes XY (D06)
  parameter int DESIGN   = DESIGN_A,
  parameter int B_MAX    = 10,         // flits per bypass burst (designs B-D)
  parameter int T_MODE   = TM_TIGHT,   // subslot rule (D10)
  parameter int REGION_N = 4,          // region side (designs C, D, D15)
  parameter int K_INIT   = 4,          // k_L from reset (designs C, D)
  parameter int EPOCH    = 1 << 15,    // epoch, cycles (designs C, D, D19)
  parameter int EJ_DEPTH = (DESIGN == DESIGN_A) ? 25 : ej_depth_b(NUM_VC, VC_DEPTH, MESH_N, B_MAX, T_MODE),
  parameter int EFW      = $clog2(EJ_DEPTH + 1)   // derived, do not set
) (
  input  logic             clk_i,
  /* verilator lint_off SYNCASYNCNET */
  input  logic             rst_ni,
  /* verilator lint_on SYNCASYNCNET */
  input  coord_t           cur_x_i,
  input  coord_t           cur_y_i,
  input  kl_t              plan_i,
  input  logic [1:0]       sum_e_i,
  input  logic [1:0]       sum_s_i,
  output logic [1:0]       sum_o,
  output kl_t              plan_o,
  output logic             tick_o,
  input  flit_t   [3:0]    in_flit_i,
  output credit_t [3:0]    in_credit_o,
  output flit_t   [3:0]    out_flit_o,
  input  credit_t [3:0]    out_credit_i,
  input  la_t     [3:0]    in_la_i,
  output la_t     [3:0]    out_la_o,
  input  cx_t     [3:0]    in_cx_i,
  output cx_t     [3:0]    out_cx_o,
  input  logic             inj_valid_i,
  output logic             inj_ready_o,
  input  flit_t            inj_flit_i,
  output logic             ej_valid_o,
  input  logic             ej_ready_i,
  output flit_t            ej_flit_o,
  output logic [EFW-1:0]   ej_free_o,
  output flit_t            ej_mon_o
);

  flit_t   [NPORTS-1:0] r_in_flit, r_out_flit;
  credit_t [NPORTS-1:0] r_in_cred, r_out_cred;

  assign r_in_flit[3:0]  = in_flit_i;
  assign in_credit_o     = r_in_cred[3:0];
  assign out_flit_o      = r_out_flit[3:0];
  assign r_out_cred[3:0] = out_credit_i;

  logic     tx_go, tx_mode;
  node_id_t tx_dst;
  logic     dec, dec_s0, dec_loc, dec_mode;
  node_id_t dec_src;
  hop_t     dec_hops;

  if (DESIGN == DESIGN_B) begin : g_tt
    logic              sub_go, act, tx_vld, nxt_go;
    logic              unused_setup, unused_last;
    sub_t              sub, nxt_sub;
    slot_t             slot;
    logic [TCYC_W-1:0] unused_cyc;
    tt_grp_t           tgt;
    coord_t            tx_x, tx_y, rx_x, rx_y, nrx_x, nrx_y, ntx_x, ntx_y;
    logic              rx_vld, rx_mode, nrx_vld, nrx_mode, ntx_vld, ntx_mode;
    hop_t              tx_hops, rx_hops, nrx_hops, ntx_hops;

    slot_counter #(
      .TT_N    (MESH_N),
      .T_SUB   (t_sub(MESH_N, B_MAX, T_MODE)),
      .S_SETUP (s_setup(MESH_N))
    ) u_cnt (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .en_i        (1'b1),
      .setup_o     (unused_setup),
      .sub_o       (sub),
      .cyc_o       (unused_cyc),
      .slot_o      (slot),
      .sub_go_o    (sub_go),
      .slot_last_o (unused_last),
      .nxt_go_o    (nxt_go),
      .nxt_sub_o   (nxt_sub)
    );

    slot_table #(.TT_N(MESH_N)) u_tab (
      .clk_i  (clk_i),
      .rst_ni (rst_ni),
      .grp_i  (tt_grp_t'(grp_of(int'(cur_x_i), int'(cur_y_i), MESH_N))),
      .slot_i (slot),
      .act_o  (act),
      .tgt_o  (tgt)
    );

    group_to_router #(.MESH_N(MESH_N), .TT_N(MESH_N)) u_g2r (
      .x_i       (cur_x_i),
      .y_i       (cur_y_i),
      .act_i     (act),
      .tgt_i     (tgt),
      .sub_i     (sub),
      .tx_vld_o  (tx_vld),
      .tx_x_o    (tx_x),
      .tx_y_o    (tx_y),
      .tx_mode_o (tx_mode),
      .tx_hops_o (tx_hops),
      .rx_vld_o  (rx_vld),
      .rx_x_o    (rx_x),
      .rx_y_o    (rx_y),
      .rx_mode_o (rx_mode),
      .rx_hops_o (rx_hops)
    );

    group_to_router #(.MESH_N(MESH_N), .TT_N(MESH_N)) u_g2r_nxt (
      .x_i       (cur_x_i),
      .y_i       (cur_y_i),
      .act_i     (act),
      .tgt_i     (tgt),
      .sub_i     (nxt_sub),
      .tx_vld_o  (ntx_vld),
      .tx_x_o    (ntx_x),
      .tx_y_o    (ntx_y),
      .tx_mode_o (ntx_mode),
      .tx_hops_o (ntx_hops),
      .rx_vld_o  (nrx_vld),
      .rx_x_o    (nrx_x),
      .rx_y_o    (nrx_y),
      .rx_mode_o (nrx_mode),
      .rx_hops_o (nrx_hops)
    );

    assign tx_go    = sub_go & tx_vld;
    assign tx_dst   = xy_to_id(tx_x, tx_y, MESH_N);
    assign dec      = nxt_go & nrx_vld;
    assign dec_s0   = (nxt_sub == '0);
    assign dec_loc  = 1'b0;
    assign dec_src  = xy_to_id(nrx_x, nrx_y, MESH_N);
    assign dec_mode = nrx_mode;
    assign dec_hops = nrx_hops;

    logic unused_tt;
    assign unused_tt = ^{unused_setup, unused_last, unused_cyc, tx_hops, rx_vld, rx_x, rx_y, rx_mode, rx_hops,
                         ntx_vld, ntx_x, ntx_y, ntx_mode, ntx_hops, plan_i, sum_e_i, sum_s_i};
    assign sum_o  = '0;
    assign plan_o = '0;
    assign tick_o = 1'b0;
  end else if (DESIGN == DESIGN_C || DESIGN == DESIGN_D) begin : g_tt2
    logic    loc, sub_go, nxt_go, act_l, act_g, tick;
    sub_t    sub_l, sub_g, nsub_l, nsub_g;
    slot_t   slot_l, slot_g;
    tt_grp_t tgt_l, tgt_g;
    kl_t     unused_kl;
    kl_t     plan_seq;                 // the plan the sequencer samples
    seq_st_t seq_st;                   // the sequencer's state (testbench lockstep check)
    logic   [3:0] tv, rv, tm, rm;
    coord_t [3:0] tx, ty, rx, ry;
    hop_t   [3:0] th, rh;

    phase_sequencer #(
      .MESH_N   (MESH_N),
      .REGION_N (REGION_N),
      .T_SUB_G  (t_sub(MESH_N, B_MAX, T_MODE)),
      .T_SUB_L  (t_sub(REGION_N, B_MAX, T_MODE)),
      .K_INIT   (K_INIT),
      .EPOCH    (EPOCH)
    ) u_seq (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .plan_i      (plan_seq),
      .loc_o       (loc),
      .slot_l_o    (slot_l),
      .sub_l_o     (sub_l),
      .nxt_sub_l_o (nsub_l),
      .slot_g_o    (slot_g),
      .sub_g_o     (sub_g),
      .nxt_sub_g_o (nsub_g),
      .sub_go_o    (sub_go),
      .nxt_go_o    (nxt_go),
      .kl_o        (unused_kl),
      .tick_o      (tick),
      .st_o        (seq_st)
    );

    if (DESIGN == DESIGN_D) begin : g_ctrl
      logic [DM_W-1:0] cl, cg;

      demand_counter #(
        .MESH_N   (MESH_N),
        .REGION_N (REGION_N),
        .NUM_VC   (NUM_VC)
      ) u_dm (
        .clk_i     (clk_i),
        .rst_ni    (rst_ni),
        .cur_x_i   (cur_x_i),
        .cur_y_i   (cur_y_i),
        .tick_i    (tick),
        .in_flit_i (r_in_flit),
        .in_cred_i (r_in_cred),
        .cl_o      (cl),
        .cg_o      (cg)
      );

      ctrl_node #(
        .MESH_N (MESH_N),
        .K_INIT (K_INIT)
      ) u_cn (
        .clk_i   (clk_i),
        .rst_ni  (rst_ni),
        .cur_x_i (cur_x_i),
        .cur_y_i (cur_y_i),
        .tick_i  (tick),
        .cl_i    (cl),
        .cg_i    (cg),
        .sum_e_i (sum_e_i),
        .sum_s_i (sum_s_i),
        .sum_o   (sum_o),
        .plan_i  (plan_i),
        .plan_o  (plan_seq)
      );

      assign plan_o = plan_seq;
    end else begin : g_fixed
      assign plan_seq = plan_i;
      assign sum_o    = '0;
      assign plan_o   = '0;
      logic unused_sum;
      assign unused_sum = ^{sum_e_i, sum_s_i};
    end
    assign tick_o = tick;

    slot_table #(.TT_N(REGION_N)) u_tab_l (
      .clk_i  (clk_i),
      .rst_ni (rst_ni),
      .grp_i  (tt_grp_t'(grp_of(int'(cur_x_i), int'(cur_y_i), REGION_N))),
      .slot_i (slot_l),
      .act_o  (act_l),
      .tgt_o  (tgt_l)
    );

    slot_table #(.TT_N(MESH_N)) u_tab_g (
      .clk_i  (clk_i),
      .rst_ni (rst_ni),
      .grp_i  (tt_grp_t'(grp_of(int'(cur_x_i), int'(cur_y_i), MESH_N))),
      .slot_i (slot_g),
      .act_o  (act_g),
      .tgt_o  (tgt_g)
    );

    group_to_router #(.MESH_N(MESH_N), .TT_N(REGION_N)) u_g2r_l (
      .x_i (cur_x_i), .y_i (cur_y_i), .act_i (act_l), .tgt_i (tgt_l), .sub_i (sub_l),
      .tx_vld_o (tv[0]), .tx_x_o (tx[0]), .tx_y_o (ty[0]), .tx_mode_o (tm[0]), .tx_hops_o (th[0]),
      .rx_vld_o (rv[0]), .rx_x_o (rx[0]), .rx_y_o (ry[0]), .rx_mode_o (rm[0]), .rx_hops_o (rh[0])
    );

    group_to_router #(.MESH_N(MESH_N), .TT_N(REGION_N)) u_g2r_ln (
      .x_i (cur_x_i), .y_i (cur_y_i), .act_i (act_l), .tgt_i (tgt_l), .sub_i (nsub_l),
      .tx_vld_o (tv[1]), .tx_x_o (tx[1]), .tx_y_o (ty[1]), .tx_mode_o (tm[1]), .tx_hops_o (th[1]),
      .rx_vld_o (rv[1]), .rx_x_o (rx[1]), .rx_y_o (ry[1]), .rx_mode_o (rm[1]), .rx_hops_o (rh[1])
    );

    group_to_router #(.MESH_N(MESH_N), .TT_N(MESH_N)) u_g2r_g (
      .x_i (cur_x_i), .y_i (cur_y_i), .act_i (act_g), .tgt_i (tgt_g), .sub_i (sub_g),
      .tx_vld_o (tv[2]), .tx_x_o (tx[2]), .tx_y_o (ty[2]), .tx_mode_o (tm[2]), .tx_hops_o (th[2]),
      .rx_vld_o (rv[2]), .rx_x_o (rx[2]), .rx_y_o (ry[2]), .rx_mode_o (rm[2]), .rx_hops_o (rh[2])
    );

    group_to_router #(.MESH_N(MESH_N), .TT_N(MESH_N)) u_g2r_gn (
      .x_i (cur_x_i), .y_i (cur_y_i), .act_i (act_g), .tgt_i (tgt_g), .sub_i (nsub_g),
      .tx_vld_o (tv[3]), .tx_x_o (tx[3]), .tx_y_o (ty[3]), .tx_mode_o (tm[3]), .tx_hops_o (th[3]),
      .rx_vld_o (rv[3]), .rx_x_o (rx[3]), .rx_y_o (ry[3]), .rx_mode_o (rm[3]), .rx_hops_o (rh[3])
    );

    logic [1:0] i_now, i_nxt;
    assign i_now    = loc ? 2'd0 : 2'd2;
    assign i_nxt    = loc ? 2'd1 : 2'd3;
    assign tx_go    = sub_go & tv[i_now];
    assign tx_dst   = xy_to_id(tx[i_now], ty[i_now], MESH_N);
    assign tx_mode  = tm[i_now];
    assign dec      = nxt_go & rv[i_nxt];
    assign dec_s0   = loc ? (nsub_l == '0) : (nsub_g == '0);
    assign dec_loc  = loc;
    assign dec_src  = xy_to_id(rx[i_nxt], ry[i_nxt], MESH_N);
    assign dec_mode = rm[i_nxt];
    assign dec_hops = rh[i_nxt];

    logic unused_tt2;
    assign unused_tt2 = ^{unused_kl, seq_st, th, rv[0], rv[2], rx[0], rx[2], ry[0], ry[2],
                          rm[0], rm[2], rh[0], rh[2], tv[1], tv[3], tx[1], tx[3], ty[1], ty[3], tm[1], tm[3]};
  end else begin : g_no_tt
    assign tx_go    = 1'b0;
    assign tx_dst   = '0;
    assign tx_mode  = 1'b0;
    assign dec      = 1'b0;
    assign dec_s0   = 1'b0;
    assign dec_loc  = 1'b0;
    assign dec_src  = '0;
    assign dec_mode = 1'b0;
    assign dec_hops = '0;
    assign sum_o    = '0;
    assign plan_o   = '0;
    assign tick_o   = 1'b0;
    logic unused_plan;
    assign unused_plan = ^{plan_i, sum_e_i, sum_s_i};
  end

  cx_t cx_inj;          // the NI's cancel token, into the router's cancel relay
  la_t la_loc;          // the router's lookahead of a burst for the NI

  router #(
    .MESH_N   (MESH_N),
    .NUM_VC   (NUM_VC),
    .VC_DEPTH (VC_DEPTH),
    .ALGO     (ALGO),
    .DESIGN   (DESIGN),
    .B_MAX    (B_MAX)
  ) u_router (
    .clk_i        (clk_i),
    .rst_ni       (rst_ni),
    .cur_x_i      (cur_x_i),
    .cur_y_i      (cur_y_i),
    .in_flit_i    (r_in_flit),
    .in_credit_o  (r_in_cred),
    .out_flit_o   (r_out_flit),
    .out_credit_i (r_out_cred),
    .in_la_i      (in_la_i),
    .out_la_o     (out_la_o),
    .in_cx_i      (in_cx_i),
    .out_cx_o     (out_cx_o),
    .cx_inj_i     (cx_inj),
    .la_loc_o     (la_loc),
    .tx_go_i      (tx_go),
    .tx_dst_i     (tx_dst),
    .tx_mode_i    (tx_mode)
  );

  ni #(
    .NUM_VC   (NUM_VC),
    .VC_DEPTH (VC_DEPTH),
    .EJ_DEPTH (EJ_DEPTH),
    .BYPASS   ((DESIGN != DESIGN_A) ? 1 : 0),
    .B_MAX    (B_MAX),
    .GAP0     (s_setup(MESH_N)),
    .GAPK     (t_sub(MESH_N, B_MAX, T_MODE)),
    .GAP0_L   (s_setup(REGION_N)),
    .GAPK_L   (t_sub(REGION_N, B_MAX, T_MODE))
  ) u_ni (
    .clk_i       (clk_i),
    .rst_ni      (rst_ni),
    .inj_valid_i (inj_valid_i),
    .inj_ready_o (inj_ready_o),
    .inj_flit_i  (inj_flit_i),
    .link_o      (r_in_flit[P_L]),
    .credit_i    (r_in_cred[P_L]),
    .ej_link_i   (r_out_flit[P_L]),
    .credit_o    (r_out_cred[P_L]),
    .ej_valid_o  (ej_valid_o),
    .ej_ready_i  (ej_ready_i),
    .ej_flit_o   (ej_flit_o),
    .ej_free_o   (ej_free_o),
    .ej_mon_o    (ej_mon_o),
    .dec_i       (dec),
    .dec_s0_i    (dec_s0),
    .dec_loc_i   (dec_loc),
    .dec_src_i   (dec_src),
    .dec_mode_i  (dec_mode),
    .dec_hops_i  (dec_hops),
    .la_loc_i    (la_loc),
    .cx_o        (cx_inj)
  );

endmodule

// =============================================================================
// ==== rtl/top/mesh_top.sv
// =============================================================================
`timescale 1ns/1ps

module mesh_top
  import noc_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int NUM_VC   = 4,
  parameter int VC_DEPTH = 5,
  parameter int ALGO     = RT_XY,
  parameter int DESIGN   = DESIGN_A,
  parameter int B_MAX    = 10,                     // flits per bypass burst (designs B-D)
  parameter int T_MODE   = sched_pkg::TM_TIGHT,    // subslot rule (D10)
  parameter int REGION_N = (MESH_N >= 4) ? 4 : MESH_N,   // region side (designs C, D)
  parameter int K_FIXED  = sched_pkg::k_fixed(MESH_N, REGION_N, B_MAX, T_MODE),  // k_L from reset
  parameter int EPOCH    = sched_pkg::epoch_len(MESH_N, REGION_N, B_MAX, T_MODE), // epoch, cycles
  parameter int K_LO     = sched_pkg::K_MIN,       // design D: clamp of k_L (D18; E7, E8 vary it)
  parameter int K_HI     = sched_pkg::k_max(MESH_N),
  parameter int EJ_DEPTH = (DESIGN == DESIGN_A) ? 25 : sched_pkg::ej_depth_b(NUM_VC, VC_DEPTH, MESH_N, B_MAX, T_MODE),
  parameter int NN       = MESH_N * MESH_N,        // derived, do not set
  parameter int EFW      = $clog2(EJ_DEPTH + 1)    // derived, do not set
) (
  input  logic                clk_i,
  /* verilator lint_off SYNCASYNCNET */
  input  logic                rst_ni,
  /* verilator lint_on SYNCASYNCNET */
  input  sched_pkg::kl_t      plan_i,
  input  logic                ctrl_pol_i,
  input  logic                ctrl_damp_i,
  input  logic                inj_valid_i [NN],
  output logic                inj_ready_o [NN],
  input  flit_t               inj_flit_i  [NN],
  output logic                ej_valid_o  [NN],
  input  logic                ej_ready_i  [NN],
  output flit_t               ej_flit_o   [NN],
  output logic  [EFW-1:0]     ej_free_o   [NN],
  output flit_t               ej_mon_o    [NN]
);

  flit_t   [3:0] t_in_flit [NN], t_out_flit [NN];
  credit_t [3:0] t_in_cred [NN], t_out_cred [NN];
  la_t     [3:0] t_in_la   [NN], t_out_la   [NN];
  cx_t     [3:0] t_in_cx   [NN], t_out_cx   [NN];
  /* verilator lint_off UNUSEDSIGNAL */
  logic    [1:0] t_sum_e [NN], t_sum_s [NN], t_sum_o [NN];
  sched_pkg::kl_t t_plan_i [NN], t_plan_o [NN];
  logic          t_tick  [NN];
  /* verilator lint_on UNUSEDSIGNAL */
  sched_pkg::kl_t c_plan;              // sched_ctrl's plan, into tile (0, 0)

  for (genvar y = 0; y < MESH_N; y++) begin : g_row
    for (genvar x = 0; x < MESH_N; x++) begin : g_col
      localparam int ID = y * MESH_N + x;

      if (y > 0) begin : g_n
        assign t_in_flit[ID][P_N]  = t_out_flit[ID - MESH_N][P_S];
        assign t_out_cred[ID][P_N] = t_in_cred[ID - MESH_N][P_S];
        assign t_in_la[ID][P_N]    = t_out_la[ID - MESH_N][P_S];
        assign t_in_cx[ID][P_N]    = t_out_cx[ID - MESH_N][P_S];
      end else begin : g_n_edge
        assign t_in_flit[ID][P_N]  = '0;
        assign t_out_cred[ID][P_N] = '0;
        assign t_in_la[ID][P_N]    = '0;
        assign t_in_cx[ID][P_N]    = '0;
      end
      if (x < MESH_N - 1) begin : g_e
        assign t_in_flit[ID][P_E]  = t_out_flit[ID + 1][P_W];
        assign t_out_cred[ID][P_E] = t_in_cred[ID + 1][P_W];
        assign t_in_la[ID][P_E]    = t_out_la[ID + 1][P_W];
        assign t_in_cx[ID][P_E]    = t_out_cx[ID + 1][P_W];
      end else begin : g_e_edge
        assign t_in_flit[ID][P_E]  = '0;
        assign t_out_cred[ID][P_E] = '0;
        assign t_in_la[ID][P_E]    = '0;
        assign t_in_cx[ID][P_E]    = '0;
      end
      if (y < MESH_N - 1) begin : g_s
        assign t_in_flit[ID][P_S]  = t_out_flit[ID + MESH_N][P_N];
        assign t_out_cred[ID][P_S] = t_in_cred[ID + MESH_N][P_N];
        assign t_in_la[ID][P_S]    = t_out_la[ID + MESH_N][P_N];
        assign t_in_cx[ID][P_S]    = t_out_cx[ID + MESH_N][P_N];
      end else begin : g_s_edge
        assign t_in_flit[ID][P_S]  = '0;
        assign t_out_cred[ID][P_S] = '0;
        assign t_in_la[ID][P_S]    = '0;
        assign t_in_cx[ID][P_S]    = '0;
      end
      if (x > 0) begin : g_w
        assign t_in_flit[ID][P_W]  = t_out_flit[ID - 1][P_E];
        assign t_out_cred[ID][P_W] = t_in_cred[ID - 1][P_E];
        assign t_in_la[ID][P_W]    = t_out_la[ID - 1][P_E];
        assign t_in_cx[ID][P_W]    = t_out_cx[ID - 1][P_E];
      end else begin : g_w_edge
        assign t_in_flit[ID][P_W]  = '0;
        assign t_out_cred[ID][P_W] = '0;
        assign t_in_la[ID][P_W]    = '0;
        assign t_in_cx[ID][P_W]    = '0;
      end

      if (DESIGN == DESIGN_D) begin : g_cn
        if (x < MESH_N - 1) begin : g_se
          assign t_sum_e[ID] = t_sum_o[ID + 1];
        end else begin : g_se_edge
          assign t_sum_e[ID] = 2'b00;
        end
        if (x == 0 && y < MESH_N - 1) begin : g_ss
          assign t_sum_s[ID] = t_sum_o[ID + MESH_N];
        end else begin : g_ss_none
          assign t_sum_s[ID] = 2'b00;
        end
        if (x > 0) begin : g_pw
          assign t_plan_i[ID] = t_plan_o[ID - 1];
        end else if (y > 0) begin : g_pn
          assign t_plan_i[ID] = t_plan_o[ID - MESH_N];
        end else begin : g_pc
          assign t_plan_i[ID] = c_plan;
        end
      end else begin : g_no_cn
        assign t_sum_e[ID]  = 2'b00;
        assign t_sum_s[ID]  = 2'b00;
        assign t_plan_i[ID] = plan_i;
      end

      tile #(
        .MESH_N   (MESH_N),
        .NUM_VC   (NUM_VC),
        .VC_DEPTH (VC_DEPTH),
        .ALGO     (ALGO),
        .DESIGN   (DESIGN),
        .EJ_DEPTH (EJ_DEPTH),
        .B_MAX    (B_MAX),
        .T_MODE   (T_MODE),
        .REGION_N (REGION_N),
        .K_INIT   (K_FIXED),
        .EPOCH    (EPOCH)
      ) u_tile (
        .clk_i        (clk_i),
        .rst_ni       (rst_ni),
        .cur_x_i      (coord_t'(x)),
        .cur_y_i      (coord_t'(y)),
        .plan_i       (t_plan_i[ID]),
        .sum_e_i      (t_sum_e[ID]),
        .sum_s_i      (t_sum_s[ID]),
        .sum_o        (t_sum_o[ID]),
        .plan_o       (t_plan_o[ID]),
        .tick_o       (t_tick[ID]),
        .in_flit_i    (t_in_flit[ID]),
        .in_credit_o  (t_in_cred[ID]),
        .out_flit_o   (t_out_flit[ID]),
        .out_credit_i (t_out_cred[ID]),
        .in_la_i      (t_in_la[ID]),
        .out_la_o     (t_out_la[ID]),
        .in_cx_i      (t_in_cx[ID]),
        .out_cx_o     (t_out_cx[ID]),
        .inj_valid_i  (inj_valid_i[ID]),
        .inj_ready_o  (inj_ready_o[ID]),
        .inj_flit_i   (inj_flit_i[ID]),
        .ej_valid_o   (ej_valid_o[ID]),
        .ej_ready_i   (ej_ready_i[ID]),
        .ej_flit_o    (ej_flit_o[ID]),
        .ej_free_o    (ej_free_o[ID]),
        .ej_mon_o     (ej_mon_o[ID])
      );

`ifndef SYNTHESIS
      // synopsys translate_off
      always_ff @(posedge clk_i) begin
        if (rst_ni) begin
          if (y == 0 && t_out_flit[ID][P_N].vld)
            $fatal(1, "%m: router %0d sent a flit north, off the mesh", ID);
          if (x == MESH_N - 1 && t_out_flit[ID][P_E].vld)
            $fatal(1, "%m: router %0d sent a flit east, off the mesh", ID);
          if (y == MESH_N - 1 && t_out_flit[ID][P_S].vld)
            $fatal(1, "%m: router %0d sent a flit south, off the mesh", ID);
          if (x == 0 && t_out_flit[ID][P_W].vld)
            $fatal(1, "%m: router %0d sent a flit west, off the mesh", ID);
          if ((y == 0 && t_out_la[ID][P_N].vld) || (x == MESH_N - 1 && t_out_la[ID][P_E].vld) ||
              (y == MESH_N - 1 && t_out_la[ID][P_S].vld) || (x == 0 && t_out_la[ID][P_W].vld))
            $fatal(1, "%m: router %0d sent a lookahead off the mesh", ID);
          if ((y == 0 && t_out_cx[ID][P_N].vld) || (x == MESH_N - 1 && t_out_cx[ID][P_E].vld) ||
              (y == MESH_N - 1 && t_out_cx[ID][P_S].vld) || (x == 0 && t_out_cx[ID][P_W].vld))
            $fatal(1, "%m: router %0d sent a cancel token off the mesh", ID);
        end
      end
      // synopsys translate_on
`endif
    end
  end

  if (DESIGN == DESIGN_D) begin : g_ctrl
    sched_ctrl #(
      .MESH_N   (MESH_N),
      .REGION_N (REGION_N),
      .K_INIT   (K_FIXED),
      .K_LO     (K_LO),
      .K_HI     (K_HI)
    ) u_ctrl (
      .clk_i    (clk_i),
      .rst_ni   (rst_ni),
      .tick_i   (t_tick[0]),
      .sum_i    (t_sum_o[0]),
      .policy_i (ctrl_pol_i),
      .damp_i   (ctrl_damp_i),
      .plan_o   (c_plan)
    );
    logic unused_d;
    assign unused_d = ^plan_i;
  end else begin : g_no_ctrl
    assign c_plan = '0;
    logic unused_c;
    assign unused_c = ^{ctrl_pol_i, ctrl_damp_i, c_plan};
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (MESH_N < 2 || MESH_N > MAX_MESH_N)
      $fatal(1, "%m: MESH_N = %0d, must be 2..%0d", MESH_N, MAX_MESH_N);
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/sched/slot_table.sv
// =============================================================================
`timescale 1ns/1ps

module slot_table
  import sched_pkg::*;
#(
  parameter int TT_N = 8      // timetable side: MESH_N (global) or REGION_N (local)
) (
  input  logic    clk_i,
  input  logic    rst_ni,
  input  tt_grp_t grp_i,      // this router's group in the timetable
  input  slot_t   slot_i,     // current slot, from slot_counter
  output logic    act_o,      // the router's group is one of the slot's groups
  output tt_grp_t tgt_o       // the other group of the slot (own group in a same-group slot)
);

  slot_t tab_q [TT_N];        // tab_q[t] = slot of the group pair {grp_i, t}

  always_ff @(posedge clk_i) begin
    if (!rst_ni) begin
      for (int t = 0; t < TT_N; t++)
        tab_q[t] <= (tt_grp_t'(t) <= grp_i) ? tri_num(grp_i) + slot_t'(t) : tri_num(tt_grp_t'(t)) + slot_t'(grp_i);
    end
  end

  always_comb begin
    act_o = 1'b0;
    tgt_o = '0;
    for (int t = 0; t < TT_N; t++) begin
      if (tab_q[t] == slot_i) begin
        act_o = 1'b1;
        tgt_o = tt_grp_t'(t);
      end
    end
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (TT_N < 2 || TT_N > 16 || !pow2(TT_N))
      $fatal(1, "%m: TT_N = %0d; the timetable side must be 2, 4, 8 or 16", TT_N);
  end
  always_ff @(posedge clk_i) begin
    if (!rst_ni) begin
      if ($isunknown(grp_i) || int'(grp_i) >= TT_N)
        $fatal(1, "%m: group %0d does not exist in a %0d x %0d timetable", grp_i, TT_N, TT_N);
    end else if ($isunknown({slot_i, act_o, tgt_o})) begin
      $fatal(1, "%m: X on slot_i, act_o or tgt_o");
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/sched/slot_counter.sv
// =============================================================================
`timescale 1ns/1ps

module slot_counter
  import sched_pkg::*;
#(
  parameter int TT_N    = 8,                  // timetable side
  parameter int T_SUB   = t_tight(8, 10),     // subslot length, cycles
  parameter int S_SETUP = s_setup(8)          // setup window, cycles
) (
  input  logic              clk_i,
  input  logic              rst_ni,
  input  logic              en_i,          // this timetable runs in this cycle
  output logic              setup_o,       // in the slot's setup window
  output sub_t              sub_o,         // subslot, 0..n-1 (0 in the setup window)
  output logic [TCYC_W-1:0] cyc_o,         // cycle inside the setup window or the subslot
  output slot_t             slot_o,        // slot, 0..n(n+1)/2 - 1
  output logic              sub_go_o,      // first cycle of a subslot
  output logic              slot_last_o,   // last cycle of the slot
  output logic              nxt_go_o,      // cancel decision for subslot nxt_sub_o
  output sub_t              nxt_sub_o
);

  localparam int NSLOT = n_slots(TT_N);

  logic              setup_q;
  sub_t              sub_q;
  logic [TCYC_W-1:0] cyc_q;
  slot_t             slot_q;
  logic              last_cyc, last_sub;

  assign last_cyc = setup_q ? (cyc_q == TCYC_W'(S_SETUP - 1)) : (cyc_q == TCYC_W'(T_SUB - 1));
  assign last_sub = (sub_q == SUB_W'(TT_N - 1));

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      setup_q <= 1'b1;
      sub_q   <= '0;
      cyc_q   <= '0;
      slot_q  <= '0;
    end else if (en_i) begin
      if (!last_cyc) begin
        cyc_q <= cyc_q + 1'b1;
      end else begin
        cyc_q <= '0;
        if (setup_q) begin
          setup_q <= 1'b0;            // subslot 0 starts
        end else if (!last_sub) begin
          sub_q <= sub_q + 1'b1;
        end else begin                // the slot ends: the next one starts with its setup window
          setup_q <= 1'b1;
          sub_q   <= '0;
          slot_q  <= (slot_q == SLOT_W'(NSLOT - 1)) ? '0 : slot_q + 1'b1;
        end
      end
    end
  end

  assign setup_o     = setup_q;
  assign sub_o       = sub_q;
  assign cyc_o       = cyc_q;
  assign slot_o      = slot_q;
  assign sub_go_o    = en_i && !setup_q && (cyc_q == '0);
  assign slot_last_o = en_i && !setup_q && last_sub && last_cyc;
  assign nxt_go_o    = en_i && (cyc_q == '0) && (setup_q || !last_sub);
  assign nxt_sub_o   = setup_q ? '0 : sub_q + 1'b1;

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (TT_N < 2 || TT_N > 16 || !pow2(TT_N))
      $fatal(1, "%m: TT_N = %0d; the timetable side must be 2, 4, 8 or 16", TT_N);
    if (S_SETUP < hmax(TT_N) + 1 || S_SETUP >= (1 << TCYC_W))
      $fatal(1, "%m: S_SETUP = %0d; a cancel token needs %0d cycles to cross the longest path (D13)",
             S_SETUP, hmax(TT_N) + 1);
    if (T_SUB < hmax(TT_N) + 1 || T_SUB >= (1 << TCYC_W))
      $fatal(1, "%m: T_SUB = %0d; a cancel token decided one subslot ahead needs %0d cycles (D38)",
             T_SUB, hmax(TT_N) + 1);
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else if ($isunknown(en_i)) begin
      $fatal(1, "%m: X on en_i");
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/sched/group_to_router.sv
// =============================================================================
`timescale 1ns/1ps

module group_to_router
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int MESH_N = 8,   // mesh side
  parameter int TT_N   = 8    // timetable side: MESH_N (global) or REGION_N (local)
) (
  input  coord_t  x_i,        // this router, chip coordinates (tie-offs)
  input  coord_t  y_i,
  input  logic    act_i,      // slot_table: the router's group is in the slot
  input  tt_grp_t tgt_i,      // slot_table: the other group of the slot
  input  sub_t    sub_i,      // the subslot
  output logic    tx_vld_o,   // this router sends a burst in the subslot ...
  output coord_t  tx_x_o,     // ... to this router
  output coord_t  tx_y_o,
  output logic    tx_mode_o,  // MODE_XY or MODE_YX
  output hop_t    tx_hops_o,
  output logic    rx_vld_o,   // a burst comes to this router in the subslot ...
  output coord_t  rx_x_o,     // ... from this router
  output coord_t  rx_y_o,
  output logic    rx_mode_o,  // mode of the incoming path
  output hop_t    rx_hops_o
);

  int       bx, by;           // region corner (0, 0 for the global timetable)
  int       g, j;             // this router's group and row in the timetable
  partner_t tp, rp;

  always_comb begin
    bx = int'(x_i) & ~(TT_N - 1);     // TT_N is a power of two
    by = int'(y_i) & ~(TT_N - 1);
    j  = int'(y_i) - by;
    g  = grp_of(int'(x_i) - bx, j, TT_N);
    tp = tx_partner(g, j, int'(tgt_i), int'(sub_i), TT_N);
    rp = rx_partner(g, j, int'(tgt_i), int'(sub_i), TT_N);

    tx_vld_o  = act_i && tp.vld;
    tx_x_o    = tx_vld_o ? coord_t'(bx + int'(tp.x)) : '0;
    tx_y_o    = tx_vld_o ? coord_t'(by + int'(tp.y)) : '0;
    tx_mode_o = tx_vld_o && tp.mode;
    tx_hops_o = tx_vld_o ? hop_t'(hops(x_i, y_i, tx_x_o, tx_y_o)) : '0;

    rx_vld_o  = act_i && rp.vld;
    rx_x_o    = rx_vld_o ? coord_t'(bx + int'(rp.x)) : '0;
    rx_y_o    = rx_vld_o ? coord_t'(by + int'(rp.y)) : '0;
    rx_mode_o = rx_vld_o && rp.mode;
    rx_hops_o = rx_vld_o ? hop_t'(hops(x_i, y_i, rx_x_o, rx_y_o)) : '0;
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (TT_N < 2 || TT_N > 16 || !pow2(TT_N) || MESH_N > MAX_MESH_N || MESH_N % TT_N != 0)
      $fatal(1, "%m: TT_N = %0d, MESH_N = %0d; the timetable side must be 2, 4, 8 or 16 and divide the mesh side",
             TT_N, MESH_N);
  end
  // synopsys translate_on
`endif

endmodule

